def main():
    import numpy as np
    root = Path(__file__).resolve().parents[1]
    checks = []
    def check(label, condition):
        checks.append(bool(condition))
        print(f"[{'PASS' if condition else 'FAIL'}] {label}")
    binding = json.loads((root/'outputs/factored_recovery_2026_10_17/landing/PROOF_INPUT_BINDING.json').read_text())
    check('181 original pins, 11 current parents and 8 provenance manifests match',len(binding['pins'])==181 and len(binding['current_parents'])==11 and len(binding['provenance_manifests'])==8 and all((root/r['path']).is_file() and hashlib.sha256((root/r['path']).read_bytes()).hexdigest()==r['sha256'] for r in binding['pins']+binding['current_parents']+binding['provenance_manifests']))

    # Generic noncommuting finite matrices test the exact ordered identity,
    # not the physical scattering estimates on the apparatus windows.
    I=np.eye(3,dtype=complex);j=.7
    Q=np.diag([np.exp(.83j),.73,-.68]);Qi=np.linalg.inv(Q)
    S=np.array([[.13+.07j,.17,-.11j],[-.09,.21,.12j],[.06j,-.08,.04]])
    power=lambda n:np.linalg.matrix_power(Q,n)
    A=np.linalg.inv(j*(Q-Qi));T=S@A
    X=power(20)@T@power(20);Z=A+Q@X@Q
    original=A@power(20)@(I-Q@np.linalg.inv(Z)@Q@(A+X))
    F=np.linalg.inv(I+power(21)@S@power(21));alpha=-power(21)@F/j
    check('noncommuting cap factorization retains sign/order/21-step phase',np.linalg.norm(Q@S-S@Q)>.1 and np.linalg.norm(original-alpha)<1e-10)
    check('all 21 retained input products cancel growing powers before estimation',max(np.linalg.norm(np.linalg.matrix_power(Q,-n)@alpha+power(21-n)@F/j) for n in range(21))<1e-10)
    wrong=-F@power(21)/j;phase20=-power(20)@np.linalg.inv(I+power(20)@S@power(20))/j
    check('wrong order and 20-step phase are detected',np.linalg.norm(wrong-alpha)>1e-7 and np.linalg.norm(phase20-alpha)>.01)

    # Arbitrary noncommuting gate load: rho=-A Dg(I+A Dg)^-1.
    Dg=np.array([[.08,.03j,-.04],[.02,.11,.01j],[-.03j,.04,-.07]])
    rho=-A@Dg@np.linalg.inv(I+A@Dg);b=np.array([1+.2j,-.3j,.4]);ba=power(17)@b
    y=(I+rho)@ba;action=-np.linalg.solve(A,rho@ba)
    check('ordered gate action equals direct driven load',np.linalg.norm(Dg@y-action)<1e-12)
    # The physical local gate preserves B channels, hence commutes with Q.
    # The arbitrary upstream forcing b remains unrestricted. This premise is
    # needed for Q^18 r Q^18 = Q^36 r; the preceding action identity did not need it.
    Gg=np.diag([.02+.03j,-.04,.05])
    Dplane=-j*Q-j*j*Gg
    rhoplane=-A@Dplane@np.linalg.inv(I+A@Dplane)
    rgate=power(-2)@rhoplane
    yplane=(I+rhoplane)@ba
    cable=ba+power(-17)@power(36)@rgate@b
    general_return=ba+power(-17)@power(18)@rgate@power(18)@b
    bad_gate=power(-2)@rho
    forbidden_return=power(36)@bad_gate@b
    ordered_return=power(18)@bad_gate@power(18)@b
    check('channel-preserving gate has two-step plane; omitted phase and noncommuting shortcut mutants detected',
          np.linalg.norm(Q@rhoplane-rhoplane@Q)<1e-12 and np.linalg.norm(cable-yplane)<1e-10
          and np.linalg.norm(general_return-yplane)<1e-10
          and np.linalg.norm((I+rgate)@ba-yplane)>1e-4
          and np.linalg.norm(forbidden_return-ordered_return)>1e-4)

    # Actual scalar slow-root branch, finite real H and full inverse derivative.
    H=np.array([[.2,.11,0,0],[.11,-.3,.07,0],[0,.07,.4,.13],[0,0,.13,-.1]])
    V=np.array([[0.],[0.],[0.],[1.]]);B=np.eye(4)[:,:2];gg=.2;jj=.3
    errors=[];omitted=[]
    for energy in (-.12,.03,.17):
        q=lambda e:(-e+1j*np.sqrt(4*gg*gg-e*e))/(2*gg)
        qp=(-1-1j*energy/np.sqrt(4*gg*gg-energy*energy))/(2*gg)
        mat=lambda e: e*np.eye(4)-H+jj*(V@V.T)*q(e)
        R=np.linalg.inv(mat(energy));F0=R@B;frozen=-R@F0
        restored=frozen-jj*R@V@(qp*(V.T@F0))
        direct=-R@(np.eye(4)+jj*(V@V.T)*qp)@F0
        step=1e-6;numeric=(np.linalg.solve(mat(energy+step),B)-np.linalg.solve(mat(energy-step),B))/(2*step)
        errors.append(max(np.linalg.norm(restored-direct),np.linalg.norm(restored-numeric)/np.linalg.norm(direct)));omitted.append(np.linalg.norm(frozen-direct))
    check('frozen-root derivative plus physical correction matches direct inverse differentiation',max(errors)<1e-7)
    check('discarding physical slow-root derivative is detected',min(omitted)>.01)

    # Decimal arithmetic of supplied ceilings does not prove their analytic premises.
    with localcontext() as ctx:
        ctx.prec=60;D=Decimal;lam=D('2e-12');g=D('5e-8');Tread=D('1e13');jhi=D('.003');jlo=D('.0027');dlo=D('2.15e-8');dhi=D('2.4e-8');a0=D('8e-18');b0=D(46000)/D('.0053')+D(290)/g;kap2=3*jhi*lam;s=(1-3*lam/jlo).sqrt();theta=(jhi*a0+kap2*b0)/s+6*kap2*(a0+b0*dhi);c3=(1-theta)*s
        check('new-point ordered-loading ceiling and denominator margin',theta<D('1.048e-4') and c3>D('.9998951'))
        action=D('.006')*D('.129')*D(460);closed=jhi*(1+D(1)/3600)*(D(60)**-18+D(60)**-17/56)/(1-D(1)/3360)*1280
        dot=D('1.901e14')+D('2.22e14')*D('.357')+8000*1090*521+8000*D('.102')*D('2e10')+D('1.3e11');full=D('1.00068')*(D('2.9e14')+D('1.28e6')/g)+30
        check('gate action, ordered four-term partial derivative and restored full ceiling arithmetic',action+closed<D('.357') and closed<D('1e-29') and dot<D('2.9e14') and full<D('3.159e14'))
        mu=3*lam**6+D(8)/3*jhi*lam**5
        check('installed sixth moment includes port term and full-input outside allowance',mu<D('2.56000001e-61') and (2*mu).sqrt()/dlo**3<D('7.3e-8'))
        n=1/(1-theta);ca=D('.944');pi_hi=D(22)/7;As=2/s+D('3.00002')/s**2;Zg=D('2e8')+D(17000)/g
        D3=ca/lam*(n*D('3.00002')*pi_hi/(2*s*s)+(3*jhi*n*n/s)*(As*(4*a0/3+2*b0*lam/3)+400*a0*lam**2+400*b0*lam**3+Zg*(pi_hi*lam/(2*s)+12*lam**2)))
        ibp=2*D('1.342e-7')/(D('3.14')*Tread)*(2*ca*lam**2*14000/(c3*(dlo*dlo+lam*lam)**D('1.5'))+2*ca*full/c3+14000*D3)
        check('recomputed inverse derivative and background IBP arithmetic',D3<D('2.24e12') and ibp<D('.000274'))
        terms=[D(x) for x in ('7.3e-8','.000046','.000274','.000432','.0000062','3e-10','1e-10')];total=sum(terms);eps=D('.00076')
        check('seven complete contributions total .0007582734 below certificate',total==D('.0007582734') and total<eps)
        exponent=-D(2500000)+4*g*Tread*(D(1).exp()-D(-1).exp())/2
        check('finite receiver cut exponent and nominal apparatus counts',exponent<D(-148000) and 2500000+243==2500243 and 2*2500000+281==5000281)
        check('record failure and normalized successful-vector arithmetic',eps**2==D('5.776e-7') and 1-eps**2==D('.9999994224') and eps+1-(1-eps**2).sqrt()<D('.000761') and 2*eps==D('.00152'))
    print('Scope: finite noncommuting cap/gate identities, three slow-root derivative samples and supplied-ceiling arithmetic. Full235-head and continuum proofs, calibration and physical premises remain separate. Historical53f571b6 is not adopted.')
    print(f'TOTAL: PASS={sum(checks)} FAIL={len(checks)-sum(checks)}')
    return 0 if all(checks) else 1


